Design:

```ts
/** How long a claim with no readable run id is trusted before it reads as stale. */
export const DEFAULT_LOCK_TTL_MINUTES = 90;

export interface LockAge {
  /** The run the open claim names; 0 when it names none (an older claim, a hand-written one). */
  run: number;
  /** When the claim comment was written, ISO. "" when unreadable. */
  at: string;
