```
if (runEnded === true) return "stale";
if (runEnded === false) return "fresh";
// unknown: the timer
const at = Date.parse(claim.at); if (!Number.isFinite(at)) return "fresh";
return now.getTime() - at >= ttlMs ? "stale" : "fresh";
