```
export type RunLiveness = "running" | "finished" | "unknown";

/** Whether the lock a claim names is stale: the run is over and nothing released the turn. */
export function lockIsStale(input: {
  run: RunLiveness;
  /** When the claim was written, an ISO instant, or "" when unreadable. */
