// domain/work/stale-lock.ts
export type RunLiveness = "running" | "finished" | "unknown";

export interface LockObservation {
  /** The open claim: whose ask it is, and the run that took it. */
  readonly run: number;
  /** Whether the newest turn event is a `waiting` ending — a PARK (#208). */
  readonly parked: boolean;
  /** How the run that holds the claim is doing, from outside. */
  readonly liveness: RunLiveness;
  /** Whether any work under this node is still open — the sub-issues a park waits on. Unread parks pass `undefined`. */
  readonly openChildren?: number;
  /** When the claim was written (ISO), or "" when the read carried no time. */
  readonly claimedAt: string;
}

export function lockIsStale(lock: LockObservation, now: Date): boolean
```

