   */
  readonly waitingOnWork?: boolean;
  /** How long the lock has stood, in minutes. `undefined` when its time could not be read. */
  readonly ageMinutes?: number;
}

export const UNIDENTIFIED_LOCK_STALE_MINUTES = 120;

export function lockVerdict(facts: LockFacts): LockVerdict {
  if (facts.runFinished === false) return "live";
  if (facts.parked) {
    if (facts.waitingOnWork === true) return "live";
    if (facts.waitingOnWork === undefined) return "unknown";
  }
  if (facts.runFinished === true) return "stale";
