/** `at` in minutes before `nowMs`, or `undefined` when it cannot be read. */
function ageMinutes(at: string, nowMs: number): number | undefined {
  const parsed = Date.parse(at);
  if (!Number.isFinite(parsed)) return undefined;
  return (nowMs - parsed) / 60_000;
}

/**
 * Whether the run behind a claim may still be holding it.
 *
 * The run's own status answers it whenever the claim names a run: GitHub reports
 * `queued`, `in_progress`, `requested`, `waiting` and `pending` for a run that has not
 * finished, so the one value that means "over" is named and everything else reads as
 * live — a status this file has not seen must not read as "nothing is running here"
 * (the same argument `merge-signals.ts` makes about its own list).
 *
 * `run` is the read the caller made, and the caller decides whether to make it: a
 * claim whose `run` is 0 passes `{read:false}`, and lands on the timer.
 */
export function claimFreshness(claim: ClaimLock, run: RunStatusRead, nowMs: number): LockFreshness {
  if (claim.run > 0) {
    if (!run.read) return "unknown";
    return run.status === "completed" ? "stale" : "fresh";
  }
  const age = ageMinutes(claim.at, nowMs);
  if (age === undefined) return "unknown";
  return age >= CLAIM_WITHOUT_RUN_MINUTES ? "stale" : "fresh";
}

/**
 * Whether a parked turn's collection is overdue — the park's own clock.
 *
 * A park's run has ALWAYS finished by definition (it ended inside a child-starting
 * call), so run facts cannot separate "the resume is about to arrive" from "it never
 * will". The parent's re-invocation is the missing step, and the only evidence about
 * it is time: the aggregation fires seconds after the last child closes, so a park
 * that has sat past the grace with nothing open under it was missed.
 */
export function parkOverdue(parkedSince: string, nowMs: number): boolean {
  const age = ageMinutes(parkedSince, nowMs);
  return age !== undefined && age >= PARK_COLLECTION_MINUTES;
}

/**
 * What a sweep should do about one node's lock.
 *
 * - `release` — the run is over and nothing is coming: write the ending that answers
 *   the claim and hand the node back to a person.
 * - `hold` — something may still hold it, or a park's collection is legitimately
 *   still on its way. Write nothing.
 * - `undetermined` — the question could not be answered. Write nothing either, but
 *   say so: silence here would be indistinguishable from "there was nothing to do".
 */
export type LockVerdict = "release" | "hold" | "undetermined";

/**
 * The sweep's judgement about one node.
 *
 * A claim that is not parked has no legitimate resumer: the run took the turn and
 * nothing but an ending can release it, so "the run is over" is the whole answer.
 *
 * A park DOES have one — the aggregation — and it is the reason three more facts are
 * required before a park is released: nothing open is left under the node, the grace
 * has passed, and the children could be read at all. All three are about not racing
 * the machinery's own resume; the cost of holding a missed park another sweep is
 * another sweep, and the cost of releasing one the aggregation is about to collect is
 * a notice saying nothing was decided beside a run that then decides something.
 */
export function lockVerdict(args: {
  readonly claim: ClaimLock;
  /** Whether the thread's newest event is a `waiting` ending — a parked turn (#208). */
  readonly parked: boolean;
  /** When that ending was written. Only read when `parked`. */
  readonly parkedSince: string;
  /** Open sub-issues under the node, or `undefined` when they could not be read. */
  readonly openChildren: number;
  readonly run: RunStatusRead;
  readonly nowMs: number;
}): LockVerdict {
  const freshness = claimFreshness(args.claim, args.run, args.nowMs);
  if (freshness === "unknown") return "undetermined";
  if (freshness === "fresh") return "hold";
  if (!args.parked) return "release";
  if (args.openChildren > 0) return "hold";
  return parkOverdue(args.parkedSince, args.nowMs) ? "release" : "hold";
}
