/**
 * The lock a node's thread holds — the claim, and whether a park is holding it.
 *
 * `claim.at` is the claim COMMENT's `created_at`, which is the marker's creation time
 * when the claim was appended to a dispatch marker (`claim_turn.ts`'s in-place path).
 * That is earlier than the claim itself, so a claim like that reads older than it is:
 * only the run-less fallback uses the time at all, and being early there means being
 * conservative about calling a lock dead — which is the safe direction.
 */
export interface ThreadLock {
  /** The claim the walk leaves open, with when its comment was written. */
  claim?: ClaimLock;
  /** Whether the newest turn event is a `waiting` ending — a parked turn (#208). */
  parked: boolean;
}

/**
 * The lock `shaped` leaves behind, read off the entries it was shaped from.
 *
 * The entries must be the ones handed to `shapedThread`, in order: the open claim is
 * matched back to the entry that carries it so the time comes from the same read, and
 * the newest `waiting` ending is what says a park is holding the turn.
 *
 * The claim is matched on ask AND run: a re-invoked parent claims the parked ask under
 * its own run id, so two claims on one ask exist during a park's collection and only the
 * later one is the lock.
 */
function lockOf(entries: readonly DatedEntry[], shaped: ShapedThread<DatedEntry>): ThreadLock {
  const parked = shaped.events[shaped.events.length - 1] === "waiting";
  if (shaped.openClaim === undefined) return { parked };
  for (let index = entries.length - 1; index >= 0; index -= 1) {
    const entry = entries[index]!;
    if (entry.quoted) continue;
    const claim = readers.claim(entry.body);
    if (claim !== undefined && claim.ask === shaped.openClaim.ask && claim.run === shaped.openClaim.run) {
