  // quotations, which the loop above skips too. Reported as an untimed claim rather than
  // as no claim, so a future divergence lands on the fallback's "cannot tell" instead of
  // on "nothing holds this node".
  return { parked, claim: { ...shaped.openClaim, at: "" } };
