  // position of its own exists. Judge it as the latest arrival — whose turn the whole
  // listed thread leaves. `keptCommentIds`' rule, expressed over the walk already made.
  if (listed === undefined) return { removed: shaped.holder === "agent", parked: lock.parked, lock };
