 *
 * One function, because two callers ask the same question of the same node and act on
 * the answer differently: the watch's sweep RELEASES a stale lock, and the guard must
 * NOT delete a person's comment under one. Two spellings of the read would let them
 * disagree about the same node, and the disagreement is the cost — a sweep releasing
 * what the guard still calls live, or the guard deleting under a lock the sweep has
 * already written off.
 *
 * The judgement itself is `domain/work/stale-lock.ts`'s; this is the I/O that feeds it.
 */
import { issueLinks } from "./issue-links.ts";
import { readRunStatus } from "./run-status.ts";
import { lockOn, type ThreadLock } from "./thread.ts";
import { lockVerdict, type LockVerdict } from "../../domain/work/stale-lock.ts";

/** A node's thread lock and what follows from it. */
export interface NodeLock {
  /** The claim and the park the thread holds, as the shaping reads them. */
  readonly lock: ThreadLock;
  readonly verdict: LockVerdict;
}

/**
 * Open sub-issues under a node, or `undefined` when they could not be read.
 *
 * `issueLinks` reports an unreadable relationship as `unavailable` rather than throwing,
 * and that distinction is load-bearing here: no children and no knowledge of the
 * children must not both read as "nothing is left under this node".
 */
function openChildrenOf(repo: string, number: string | number): number | undefined {
  const links = issueLinks(repo, Number(number));
  if (links.unavailable !== undefined) return undefined;
  return links.children.filter((child) => child.state === "open").length;
}

/**
 * Read one node's lock and judge it.
 *
 * Throws when the thread cannot be read — a failed read is not "nothing holds this
 * node", and both callers have something to say about not knowing. The run-status and
 * children reads degrade instead, to `undetermined`, because each of them is only ever
 * asked to refine an answer the thread already gave.
 */
export function readNodeLock(repo: string, number: string | number, nowMs: number): NodeLock {
  const lock = lockOn(repo, number);
  // The run is only asked about when a claim names one: the run-less fallback is the
  // timer, and asking GitHub about run 0 would be a request whose answer cannot be used.
  const run = lock.claim !== undefined && lock.claim.run > 0
    ? readRunStatus(repo, lock.claim.run)
    : ({ read: false, why: "the claim names no run" } as const);
  const openChildren = lock.park !== undefined ? openChildrenOf(repo, number) : 0;
  const verdict = lockVerdict({
    claim: lock.claim,
    parked: lock.park !== undefined,
    parkedSince: lock.park?.at ?? "",
    openChildren,
    run,
    nowMs,
  });
  return { lock, verdict };
}
